import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import 'package:shared_preferences/shared_preferences.dart';
import '../models/models.dart';
import '../services/storage_service.dart';
import '../widgets/app_card.dart';

class HomeScreen extends StatefulWidget{const HomeScreen({super.key});@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{
 List<AgendaEvent> events=[];List<Meal> meals=[];List<MoneyTransaction> finance=[];List<WorkoutPlan> plans=[];Map<String,double>? goals;bool loading=true;
 String get today=>DateFormat('yyyy-MM-dd').format(DateTime.now());
 @override void initState(){super.initState();_load();}
 Future<void> _load()async{events=(await StorageService.read('agenda')).map(AgendaEvent.fromJson).toList();meals=(await StorageService.read('meals')).map(Meal.fromJson).toList();finance=(await StorageService.read('finance')).map(MoneyTransaction.fromJson).toList();plans=(await StorageService.read('workout_plans')).map(WorkoutPlan.fromJson).toList();final p=await SharedPreferences.getInstance();final g=p.getString('nutrition_goals')?.split('|');if(g!=null&&g.length==4){goals={'calories':double.tryParse(g[0])??0,'protein':double.tryParse(g[1])??0,'carbs':double.tryParse(g[2])??0,'fat':double.tryParse(g[3])??0};}if(mounted)setState(()=>loading=false);}
 @override Widget build(BuildContext context){if(loading)return const Center(child:CircularProgressIndicator());final now=DateTime.now();final ev=events.where((e)=>e.date==today).toList()..sort((a,b)=>a.start.compareTo(b.start));final m=meals.where((x)=>x.date==today).toList();final kcal=m.fold(0.0,(s,x)=>s+x.calories);final protein=m.fold(0.0,(s,x)=>s+x.protein);final carbs=m.fold(0.0,(s,x)=>s+x.carbs);final fat=m.fold(0.0,(s,x)=>s+x.fat);final inc=finance.where((x)=>x.income).fold(0.0,(s,x)=>s+x.amount);final exp=finance.where((x)=>!x.income).fold(0.0,(s,x)=>s+x.amount);final workouts=plans.where((x)=>x.weekdays.contains(now.weekday)).toList();return SafeArea(child:ListView(padding:const EdgeInsets.fromLTRB(16,14,16,30),children:[Text('Olá! 👋',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),Text(DateFormat("EEEE, dd 'de' MMMM",'pt_BR').format(now)),const SizedBox(height:16),AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Seu dia',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:14),Row(children:[_mini(Icons.event_outlined,'Agenda','${ev.length}'),_mini(Icons.fitness_center,'Treinos','${workouts.length}'),_mini(Icons.restaurant_outlined,'Refeições','${m.length}')])])),AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Próximo compromisso',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),if(ev.isEmpty)const Text('Nada agendado para hoje.') else ListTile(contentPadding:EdgeInsets.zero,leading:const CircleAvatar(child:Icon(Icons.event)),title:Text(ev.first.title),subtitle:Text('${ev.first.start}${ev.first.description.isEmpty?'':' • ${ev.first.description}'}'))])),AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Alimentação de hoje',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:12),Row(children:[_stat('${kcal.toStringAsFixed(0)}','kcal'),_stat('${protein.toStringAsFixed(0)}g','proteína'),_stat('${carbs.toStringAsFixed(0)}g','carbo'),_stat('${fat.toStringAsFixed(0)}g','gordura')]),if(goals!=null)Padding(padding:const EdgeInsets.only(top:12),child:LinearProgressIndicator(value:goals!['calories']!<=0?0:(kcal/goals!['calories']!).clamp(0.0,1.0),minHeight:8))])),AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Financeiro do mês',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:12),Row(children:[_stat('R$ ${inc.toStringAsFixed(0)}','entradas'),_stat('R$ ${exp.toStringAsFixed(0)}','despesas'),_stat('R$ ${(inc-exp).toStringAsFixed(0)}','resultado')])])),if(workouts.isNotEmpty)AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Treinos de hoje',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),...workouts.map((p)=>ListTile(contentPadding:EdgeInsets.zero,leading:const CircleAvatar(child:Icon(Icons.fitness_center)),title:Text(p.name),subtitle:Text('${p.exercisesFor(now.weekday).length} exercícios')))]))]));}
 Widget _mini(IconData icon,String label,String value)=>Expanded(child:Column(children:[Icon(icon),const SizedBox(height:5),Text(value,style:const TextStyle(fontWeight:FontWeight.bold)),Text(label,style:Theme.of(context).textTheme.bodySmall)]));
 Widget _stat(String value,String label)=>Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(value,style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.bold)),Text(label,style:Theme.of(context).textTheme.bodySmall)]));
}
